{
  "name": "Automated Parking Penalty System",
  "description": "An AI-powered CCTV monitoring system that detects illegal parking, extracts license plates using Gemini, and generates digital challans automatically.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Vehicle {
  id: string;
  plateNumber: string;
  ownerName: string;
  vehicleType: string;
  color: string;
  detectedAt: Date;
  status: 'monitoring' | 'violation' | 'cleared';
  durationSeconds: number;
}

export interface Violation {
  id: string;
  vehicleId: string;
  plateNumber: string;
  ownerName: string;
  timestamp: string;
  fineAmount: number;
  status: 'Pending' | 'Paid';
  evidenceImage: string;
  location: string;
}

export interface User {
  id: string;
  username: string;
  role: 'admin' | 'officer';
  location: string;
}

export interface DetectionResult {
  vehiclePresent: boolean;
  plateDetected: string | null;
  vehicleType?: string;
  color?: string;
  confidence: number;
}

export const NO_PARKING_ZONE_POLYGON = [
  { x: 0.2, y: 0.3 },
  { x: 0.8, y: 0.3 },
  { x: 0.9, y: 0.8 },
  { x: 0.1, y: 0.8 }
];

export const PENALTY_THRESHOLD_SECONDS = 120; // 2 minutes
export const SCAN_INTERVAL_MS = 5000; // Scan every 5 seconds for simulation
export const MOCK_LOCATION = "Central Business District - Zone A4";

export const MOCK_OWNERS: Record<string, string> = {
  "MH12AB1234": "John Doe",
  "KA01HH9999": "Sarah Connor",
  "DL3CAK4422": "Robert Miller",
  "UP16BE5566": "Amit Sharma",
  "UNKNOWN": "Registry Search Pending"
};

import { GoogleGenAI, Type } from "@google/genai";
import { DetectionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeFrame = async (base64Image: string): Promise<DetectionResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: base64Image,
              },
            },
            {
              text: `Analyze this CCTV frame for parking enforcement. 
              Determine if there is a vehicle prominently parked in the center.
              Extract the license plate number if visible.
              Return the result in JSON format with fields: vehiclePresent (boolean), plateDetected (string or null), vehicleType (string), color (string), confidence (number 0-1).`
            }
          ],
        },
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vehiclePresent: { type: Type.BOOLEAN },
            plateDetected: { type: Type.STRING, nullable: true },
            vehicleType: { type: Type.STRING },
            color: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
          },
          required: ["vehiclePresent", "plateDetected", "confidence"],
        },
      },
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return { vehiclePresent: false, plateDetected: null, confidence: 0 };
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, Shield, LogOut, Car, Timer, AlertCircle, Database, Search, Bell } from 'lucide-react';
import { Vehicle, Violation, User } from '../types';
import { analyzeFrame } from '../services/geminiService';
import ViolationHistory from './ViolationHistory';
import { NO_PARKING_ZONE_POLYGON, SCAN_INTERVAL_MS, PENALTY_THRESHOLD_SECONDS, MOCK_LOCATION, MOCK_OWNERS } from '../constants';

interface Props {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ user, onLogout }) => {
  const [activeVehicle, setActiveVehicle] = useState<Vehicle | null>(null);
  const [violations, setViolations] = useState<Violation[]>([]);
  const [isScanning, setIsScanning] = useState(true);
  const [lastScanResult, setLastScanResult] = useState<string>('System initialized. Waiting for feed...');
  const [elapsedTime, setElapsedTime] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Setup Camera
  useEffect(() => {
    async function setupCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { width: 1280, height: 720, facingMode: 'environment' } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Camera access denied", err);
        setLastScanResult('Camera Access Denied. Please enable camera permissions.');
      }
    }
    setupCamera();
  }, []);

  const triggerPenalty = useCallback((vehicle: Vehicle, evidenceImage: string) => {
    const newViolation: Violation = {
      id: `CH-${Date.now()}`,
      vehicleId: vehicle.id,
      plateNumber: vehicle.plateNumber,
      ownerName: vehicle.ownerName,
      timestamp: new Date().toLocaleTimeString(),
      fineAmount: 150,
      status: 'Pending',
      evidenceImage,
      location: MOCK_LOCATION
    };
    setViolations(prev => [newViolation, ...prev]);
    setActiveVehicle(null);
    setElapsedTime(0);
    setLastScanResult(`PENALTY ISSUED for ${vehicle.plateNumber}`);
  }, []);

  const performScan = useCallback(async () => {
    if (!videoRef.current || !canvasRef.current || !isScanning) return;

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // Overlay No Parking Zone
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 4;
    ctx.setLineDash([10, 5]);
    ctx.beginPath();
    NO_PARKING_ZONE_POLYGON.forEach((point, i) => {
      const px = point.x * canvas.width;
      const py = point.y * canvas.height;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.closePath();
    ctx.stroke();

    ctx.fillStyle = 'rgba(239, 68, 68, 0.15)';
    ctx.fill();

    const frameData = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
    setLastScanResult('Analyzing frame...');

    const result = await analyzeFrame(frameData);

    if (result.vehiclePresent) {
      if (!activeVehicle) {
        const plate = result.plateDetected || "SCANNING...";
        const owner = MOCK_OWNERS[plate] || "Registry Search Pending";

        const newVehicle: Vehicle = {
          id: `V-${Date.now()}`,
          plateNumber: plate,
          ownerName: owner,
          vehicleType: result.vehicleType || "Vehicle",
          color: result.color || "Unknown",
          detectedAt: new Date(),
          status: 'monitoring',
          durationSeconds: 0
        };
        setActiveVehicle(newVehicle);
        setLastScanResult(`New vehicle detected: ${plate}`);
      } else {
        // Vehicle still there, update plate if it was missing
        if (activeVehicle.plateNumber === "SCANNING..." && result.plateDetected) {
            const plate = result.plateDetected;
            const owner = MOCK_OWNERS[plate] || "Registry Search Pending";
            setActiveVehicle(prev => prev ? ({ ...prev, plateNumber: plate, ownerName: owner }) : null);
        }
        setLastScanResult(`Vehicle ${activeVehicle.plateNumber} is still in No Parking Zone`);
      }
    } else {
      if (activeVehicle) {
        setLastScanResult('Vehicle cleared the zone.');
        setActiveVehicle(null);
        setElapsedTime(0);
      } else {
        setLastScanResult('Zone Clear. No violations detected.');
      }
    }
  }, [activeVehicle, isScanning]);

  // Main Scan Loop
  useEffect(() => {
    const interval = setInterval(() => {
      performScan();
    }, SCAN_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [performScan]);

  // Duration Timer Simulation
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (activeVehicle) {
      timer = setInterval(() => {
        setElapsedTime(prev => {
          const next = prev + 1;
          // In real life this is 120s (2 mins). 
          // For demo purposes, let's speed it up or keep it 120 but display progress.
          if (next >= PENALTY_THRESHOLD_SECONDS && activeVehicle.plateNumber !== "SCANNING...") {
             const canvas = canvasRef.current;
             const evidence = canvas ? canvas.toDataURL('image/jpeg') : '';
             triggerPenalty(activeVehicle, evidence);
             return 0;
          }
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [activeVehicle, triggerPenalty]);

  const progressPercentage = Math.min((elapsedTime / PENALTY_THRESHOLD_SECONDS) * 100, 100);

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-slate-900">
      {/* Sidebar */}
      <aside className="w-full lg:w-72 bg-slate-800 border-r border-slate-700 flex flex-col">
        <div className="p-6 flex items-center gap-3 border-b border-slate-700">
          <div className="bg-red-600 p-2 rounded-lg">
            <Shield className="text-white w-6 h-6" />
          </div>
          <h1 className="font-bold text-xl leading-tight">ParkGuard<br/><span className="text-sm font-normal text-slate-400">Security Suite</span></h1>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider px-2 mb-2">Main Menu</div>
          <button className="w-full flex items-center gap-3 px-3 py-2 bg-red-600/10 text-red-500 rounded-lg font-medium">
            <Camera className="w-5 h-5" /> Live Monitoring
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Database className="w-5 h-5" /> Database Search
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Search className="w-5 h-5" /> Plate Inquiry
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Bell className="w-5 h-5" /> Notifications
          </button>
        </nav>

        <div className="p-4 border-t border-slate-700">
          <div className="bg-slate-900/50 p-3 rounded-lg flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-slate-300 font-bold">
              {user.username.charAt(0).toUpperCase()}
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-sm font-medium truncate">{user.username}</p>
              <p className="text-xs text-slate-500 truncate">{user.role.toUpperCase()}</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center gap-2 px-3 py-2 text-slate-400 hover:text-red-400 transition-colors text-sm"
          >
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Content */}
      <main className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-6">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold">Active CCTV Monitoring</h2>
            <p className="text-slate-400 flex items-center gap-1">
              <MapPinIcon className="w-4 h-4" /> {MOCK_LOCATION}
            </p>
          </div>
          <div className="flex gap-2">
            <div className="bg-slate-800 px-4 py-2 rounded-lg border border-slate-700 flex items-center gap-4">
              <div className="text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Total Fines</p>
                <p className="text-lg font-bold">${violations.length * 150}</p>
              </div>
              <div className="h-8 w-px bg-slate-700" />
              <div className="text-center">
                <p className="text-xs text-slate-500 uppercase font-bold">Today's Logs</p>
                <p className="text-lg font-bold">{violations.length}</p>
              </div>
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
          {/* Feed Container */}
          <div className="xl:col-span-2 space-y-4">
            <div className="relative aspect-video bg-black rounded-2xl overflow-hidden border-4 border-slate-800 shadow-2xl">
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted 
                className="w-full h-full object-cover grayscale brightness-75"
              />
              <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" />

              {/* UI Overlays on Feed */}
              <div className="absolute top-4 left-4 bg-red-600/80 backdrop-blur-sm text-white px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider flex items-center gap-2 animate-pulse">
                <div className="w-2 h-2 bg-white rounded-full" /> Live
              </div>

              <div className="absolute top-4 right-4 flex gap-2">
                 <button 
                  onClick={() => setIsScanning(!isScanning)}
                  className={`px-4 py-1.5 rounded-full text-xs font-bold uppercase backdrop-blur-sm border transition-all ${
                    isScanning ? 'bg-slate-900/60 border-slate-700 text-white' : 'bg-green-600 border-green-500 text-white'
                  }`}
                 >
                   {isScanning ? 'Pause System' : 'Resume System'}
                 </button>
              </div>

              <div className="absolute bottom-4 left-4 right-4 flex justify-between items-end">
                <div className="bg-slate-900/80 backdrop-blur-md p-3 rounded-xl border border-white/10 max-w-[70%]">
                  <div className="flex items-center gap-2 mb-1">
                    <AlertCircle className="w-4 h-4 text-slate-400" />
                    <span className="text-xs text-slate-400 font-medium uppercase">Analysis Log</span>
                  </div>
                  <p className="text-sm font-mono text-emerald-400">{lastScanResult}</p>
                </div>
                <div className="text-right text-xs text-white/50 font-mono">
                  {new Date().toLocaleDateString()}<br/>
                  {new Date().toLocaleTimeString()}
                </div>
              </div>
            </div>

            <ViolationHistory violations={violations} />
          </div>

          {/* Right Panel: Detection Detail */}
          <div className="space-y-6">
            <section className="bg-slate-800 rounded-2xl border border-slate-700 p-6">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                <Car className="text-slate-400 w-5 h-5" />
                Detection Status
              </h3>

              {activeVehicle ? (
                <div className="space-y-6">
                  <div className="flex flex-col items-center justify-center p-6 bg-slate-900 rounded-xl border border-red-500/30">
                    <div className="text-center mb-4">
                      <p className="text-xs text-slate-500 uppercase font-bold tracking-widest mb-1">Identified Plate</p>
                      <h4 className="text-3xl font-black font-mono tracking-tighter text-white bg-slate-800 px-6 py-2 rounded-lg border-b-4 border-slate-700">
                        {activeVehicle.plateNumber}
                      </h4>
                    </div>

                    <div className="grid grid-cols-2 gap-4 w-full">
                      <div className="bg-slate-800/50 p-3 rounded-lg">
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Owner</p>
                        <p className="text-sm font-medium">{activeVehicle.ownerName}</p>
                      </div>
                      <div className="bg-slate-800/50 p-3 rounded-lg">
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Vehicle</p>
                        <p className="text-sm font-medium">{activeVehicle.color} {activeVehicle.vehicleType}</p>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between items-end">
                      <p className="text-sm font-semibold flex items-center gap-2">
                        <Timer className="w-4 h-4 text-amber-500" />
                        Penalty Countdown
                      </p>
                      <p className="text-xs font-mono text-slate-400">
                        {elapsedTime}s / {PENALTY_THRESHOLD_SECONDS}s
                      </p>
                    </div>
                    <div className="h-3 bg-slate-900 rounded-full overflow-hidden border border-slate-700">
                      <div 
                        className={`h-full transition-all duration-1000 ${progressPercentage > 80 ? 'bg-red-500' : 'bg-amber-500'}`}
                        style={{ width: `${progressPercentage}%` }}
                      />
                    </div>
                    <p className="text-[10px] text-slate-500 italic text-center">
                      Automatic challan will be issued once the timer reaches 120s.
                    </p>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-12 text-slate-600 border-2 border-dashed border-slate-700 rounded-xl">
                  <Car className="w-12 h-12 mb-3 opacity-20" />
                  <p className="text-sm font-medium">Scanning for vehicles...</p>
                  <p className="text-xs">No active violations in target zone.</p>
                </div>
              )}
            </section>

            <section className="bg-gradient-to-br from-indigo-600/20 to-slate-800 rounded-2xl border border-slate-700 p-6">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                <AlertCircle className="text-indigo-400 w-5 h-5" />
                Enforcement Notice
              </h3>
              <p className="text-sm text-slate-300 mb-4 leading-relaxed">
                As per municipal regulation <strong>B-204</strong>, vehicles parked in designated Red Zones for over 2 minutes are subject to an immediate $150 penalty.
              </p>
              <div className="space-y-2">
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500">Fine Amount:</span>
                  <span className="font-bold">$150.00</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500">Processing Fee:</span>
                  <span className="font-bold">$0.00 (Govt-subsidized)</span>
                </div>
                <div className="pt-2 border-t border-slate-700 flex justify-between text-sm">
                  <span className="font-bold">Total Liability:</span>
                  <span className="font-black text-red-500">$150.00</span>
                </div>
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
};

const MapPinIcon = ({ className }: { className?: string }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
  </svg>
);

export default Dashboard;

import React, { useState } from 'react';
import { Shield, Lock, User as UserIcon, ArrowRight } from 'lucide-react';
import { User } from '../types';

interface Props {
  onLogin: (user: User) => void;
}

const Login: React.FC<Props> = ({ onLogin }) => {
