            <div className="bg-gradient-to-tr from-red-600 to-red-400 p-4 rounded-2xl shadow-lg mb-4">
              <Shield className="text-white w-10 h-10" />
            </div>
            <h1 className="text-2xl font-bold tracking-tight">ParkGuard Terminal</h1>
            <p className="text-slate-500 text-sm mt-1">Authorized Enforcement Personnel Only</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Username</label>
              <div className="relative">
                <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl py-3 pl-11 pr-4 text-slate-100 placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-red-500/40 transition-all"
                  placeholder="Operator ID"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Secure Passkey</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl py-3 pl-11 pr-4 text-slate-100 placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-red-500/40 transition-all"
                  placeholder="••••••••"
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-red-600 hover:bg-red-500 disabled:bg-slate-700 text-white font-bold py-3 px-4 rounded-xl shadow-lg shadow-red-600/20 flex items-center justify-center gap-2 transition-all transform hover:-translate-y-0.5"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  Establish Connection
                  <ArrowRight className="w-5 h-5" />
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center text-xs text-slate-500">
            System monitored by Gov-Enforce Network v2.4.1
          </div>
        </div>

        <div className="mt-6 flex justify-center gap-4 text-slate-500 text-xs font-medium">
          <a href="#" className="hover:text-white transition-colors">Privacy Policy</a>
          <span className="opacity-20">•</span>
          <a href="#" className="hover:text-white transition-colors">Terms of Service</a>
          <span className="opacity-20">•</span>
          <a href="#" className="hover:text-white transition-colors">System Status</a>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import { User } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  return (
    <div className="font-sans antialiased text-slate-100 selection:bg-red-500 selection:text-white">
      {currentUser ? (
        <Dashboard user={currentUser} onLogout={handleLogout} />
