import { GoogleGenAI, Type } from "@google/genai";
import { DetectionResult } from "../types";

export const analyzeFrame = async (base64Image: string): Promise<DetectionResult> => {
  try {
    // Initialize GoogleGenAI within the function to ensure it uses the most current API key from process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Analyze this CCTV frame for parking enforcement. 
            Determine if there is a vehicle prominently parked in the center.
            Extract the license plate number if visible.
            Return the result in JSON format with fields: vehiclePresent (boolean), plateDetected (string or null), vehicleType (string), color (string), confidence (number 0-1).`
          }
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vehiclePresent: { type: Type.BOOLEAN },
            plateDetected: { type: Type.STRING },
            vehicleType: { type: Type.STRING },
            color: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
          },
          required: ["vehiclePresent", "plateDetected", "confidence"],
        },
      },
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return { vehiclePresent: false, plateDetected: null, confidence: 0 };
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, Shield, LogOut, Car, Timer, AlertCircle, Database, Search, Bell } from 'lucide-react';
import { Vehicle, Violation, User } from '../types';
import { analyzeFrame } from '../services/geminiService';
import ViolationHistory from './ViolationHistory';
import { NO_PARKING_ZONE_POLYGON, SCAN_INTERVAL_MS, PENALTY_THRESHOLD_SECONDS, MOCK_LOCATION, MOCK_OWNERS } from '../constants';

interface Props {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ user, onLogout }) => {
  const [activeVehicle, setActiveVehicle] = useState<Vehicle | null>(null);
  const [violations, setViolations] = useState<Violation[]>([]);
  const [isScanning, setIsScanning] = useState(true);
  const [lastScanResult, setLastScanResult] = useState<string>('System initialized. Waiting for feed...');
  const [elapsedTime, setElapsedTime] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Setup Camera
  useEffect(() => {
    async function setupCamera() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { width: 1280, height: 720, facingMode: 'environment' } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Camera access denied", err);
        setLastScanResult('Camera Access Denied. Please enable camera permissions.');
      }
    }
    setupCamera();
  }, []);

  const triggerPenalty = useCallback((vehicle: Vehicle, evidenceImage: string) => {
    const newViolation: Violation = {
      id: `CH-${Date.now()}`,
      vehicleId: vehicle.id,
      plateNumber: vehicle.plateNumber,
      ownerName: vehicle.ownerName,
      timestamp: new Date().toLocaleTimeString(),
      fineAmount: 150,
      status: 'Pending',
      evidenceImage,
      location: MOCK_LOCATION
    };
    setViolations(prev => [newViolation, ...prev]);
    setActiveVehicle(null);
    setElapsedTime(0);
    setLastScanResult(`PENALTY ISSUED for ${vehicle.plateNumber}`);
  }, []);

  const performScan = useCallback(async () => {
    if (!videoRef.current || !canvasRef.current || !isScanning) return;

    const canvas = canvasRef.current;
    const video = videoRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

    // Overlay No Parking Zone
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 4;
    ctx.setLineDash([10, 5]);
    ctx.beginPath();
    NO_PARKING_ZONE_POLYGON.forEach((point, i) => {
      const px = point.x * canvas.width;
      const py = point.y * canvas.height;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.closePath();
    ctx.stroke();

    ctx.fillStyle = 'rgba(239, 68, 68, 0.15)';
    ctx.fill();

    const frameData = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
    setLastScanResult('Analyzing frame...');

    const result = await analyzeFrame(frameData);

    if (result.vehiclePresent) {
      if (!activeVehicle) {
        const plate = result.plateDetected || "SCANNING...";
        const owner = MOCK_OWNERS[plate] || "Registry Search Pending";

        const newVehicle: Vehicle = {
          id: `V-${Date.now()}`,
          plateNumber: plate,
          ownerName: owner,
          vehicleType: result.vehicleType || "Vehicle",
          color: result.color || "Unknown",
          detectedAt: new Date(),
          status: 'monitoring',
          durationSeconds: 0
        };
        setActiveVehicle(newVehicle);
        setLastScanResult(`New vehicle detected: ${plate}`);
      } else {
        // Vehicle still there, update plate if it was missing
        if (activeVehicle.plateNumber === "SCANNING..." && result.plateDetected) {
            const plate = result.plateDetected;
            const owner = MOCK_OWNERS[plate] || "Registry Search Pending";
            setActiveVehicle(prev => prev ? ({ ...prev, plateNumber: plate, ownerName: owner }) : null);
        }
        setLastScanResult(`Vehicle ${activeVehicle.plateNumber} is still in No Parking Zone`);
      }
    } else {
      if (activeVehicle) {
        setLastScanResult('Vehicle cleared the zone.');
        setActiveVehicle(null);
        setElapsedTime(0);
      } else {
        setLastScanResult('Zone Clear. No violations detected.');
      }
    }
  }, [activeVehicle, isScanning]);

  // Main Scan Loop
  useEffect(() => {
    const interval = setInterval(() => {
      performScan();
    }, SCAN_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [performScan]);

  // Duration Timer Simulation
  useEffect(() => {
    // Fixed: Use 'any' type to resolve 'Cannot find namespace NodeJS' error in browser environment
    let timer: any;
    if (activeVehicle) {
