          <div className="bg-red-600 p-2 rounded-lg">
            <Shield className="text-white w-6 h-6" />
          </div>
          <h1 className="font-bold text-xl leading-tight">ParkGuard<br/><span className="text-sm font-normal text-slate-400">Security Suite</span></h1>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider px-2 mb-2">Main Menu</div>
          <button className="w-full flex items-center gap-3 px-3 py-2 bg-red-600/10 text-red-500 rounded-lg font-medium">
            <Camera className="w-5 h-5" /> Live Monitoring
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Database className="w-5 h-5" /> Database Search
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Search className="w-5 h-5" /> Plate Inquiry
          </button>
          <button className="w-full flex items-center gap-3 px-3 py-2 text-slate-400 hover:bg-slate-700 hover:text-white rounded-lg transition-colors">
            <Bell className="w-5 h-5" /> Notifications
          </button>
        </nav>

        <div className="p-4 border-t border-slate-700">
          <div className="bg-slate-900/50 p-3 rounded-lg flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-slate-300 font-bold">
              {user.username.charAt(0).toUpperCase()}
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-sm font-medium truncate">{user.username}</p>
              <p className="text-xs text-slate-500 truncate">{user.role.toUpperCase()}</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center gap-2 px-3 py-2 text-slate-400 hover:text-red-400 transition-colors text-sm"
          >
            <LogOut className="w-4 h-4" /> Sign Out
          </button>
        </div>
      </aside>

      {/* Content */}
      <main className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-6">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold">Active CCTV Monitoring</h2>
            <p className="text-slate-400 flex items-center gap-1">
              <MapPinIcon className="w-4 h-4" /> {MOCK_LOCATION}
            </p>
          </div>
