                  <div className="flex flex-col items-center justify-center p-6 bg-slate-900 rounded-xl border border-red-500/30">
                    <div className="text-center mb-4">
                      <p className="text-xs text-slate-500 uppercase font-bold tracking-widest mb-1">Identified Plate</p>
                      <h4 className="text-3xl font-black font-mono tracking-tighter text-white bg-slate-800 px-6 py-2 rounded-lg border-b-4 border-slate-700">
                        {activeVehicle.plateNumber}
                      </h4>
                    </div>

                    <div className="grid grid-cols-2 gap-4 w-full">
                      <div className="bg-slate-800/50 p-3 rounded-lg">
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Owner</p>
                        <p className="text-sm font-medium">{activeVehicle.ownerName}</p>
                      </div>
                      <div className="bg-slate-800/50 p-3 rounded-lg">
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Vehicle</p>
                        <p className="text-sm font-medium">{activeVehicle.color} {activeVehicle.vehicleType}</p>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <div className="flex justify-between items-end">
                      <p className="text-sm font-semibold flex items-center gap-2">
                        <Timer className="w-4 h-4 text-amber-500" />
                        Penalty Countdown
                      </p>
                      <p className="text-xs font-mono text-slate-400">
                        {elapsedTime}s / {PENALTY_THRESHOLD_SECONDS}s
                      </p>
                    </div>
                    <div className="h-3 bg-slate-900 rounded-full overflow-hidden border border-slate-700">
                      <div 
                        className={`h-full transition-all duration-1000 ${progressPercentage > 80 ? 'bg-red-500' : 'bg-amber-500'}`}
                        style={{ width: `${progressPercentage}%` }}
                      />
                    </div>
                    <p className="text-[10px] text-slate-500 italic text-center">
                      Automatic challan will be issued once the timer reaches 120s.
                    </p>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-12 text-slate-600 border-2 border-dashed border-slate-700 rounded-xl">
                  <Car className="w-12 h-12 mb-3 opacity-20" />
                  <p className="text-sm font-medium">Scanning for vehicles...</p>
                  <p className="text-xs">No active violations in target zone.</p>
                </div>
              )}
            </section>

            <section className="bg-gradient-to-br from-indigo-600/20 to-slate-800 rounded-2xl border border-slate-700 p-6">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                <AlertCircle className="text-indigo-400 w-5 h-5" />
                Enforcement Notice
              </h3>
              <p className="text-sm text-slate-300 mb-4 leading-relaxed">
                As per <strong>Section 122 of the Motor Vehicles Act</strong>, vehicles parked in designated No Parking Zones for over 2 minutes are subject to an immediate ₹500 penalty.
              </p>
              <div className="space-y-2">
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500">Fine Amount:</span>
                  <span className="font-bold">₹500.00</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-slate-500">Processing Fee:</span>
                  <span className="font-bold">₹0.00 (Govt-subsidized)</span>
                </div>
                <div className="pt-2 border-t border-slate-700 flex justify-between text-sm">
                  <span className="font-bold">Total Liability:</span>
                  <span className="font-black text-red-500">₹500.00</span>
                </div>
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
};

